-- Restore the pgvector HNSW ANN index that a Prisma-autogenerated migration dropped (the embedding
-- column is Unsupported, so Prisma's diff didn't track it and emitted a DROP). Without this, every
-- KNN over vector_documents degrades to a sequential scan. IF NOT EXISTS so it's idempotent, and
-- it lives in a hand-written migration Prisma won't regenerate over.
CREATE INDEX IF NOT EXISTS "vector_documents_embedding_hnsw"
  ON "vector_documents" USING hnsw ("embedding" vector_cosine_ops);
